CREATE TABLE IF NOT EXISTS visit_sessions (id TEXT PRIMARY KEY,started_at INTEGER NOT NULL,last_at INTEGER NOT NULL,source TEXT NOT NULL,medium TEXT NOT NULL,ad_campaign TEXT NOT NULL,ad TEXT NOT NULL,ref TEXT NOT NULL,param TEXT NOT NULL,referrer_domain TEXT NOT NULL,language TEXT NOT NULL,landing TEXT NOT NULL,views INTEGER NOT NULL DEFAULT 0,engaged INTEGER NOT NULL DEFAULT 0,outbound INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS visits_started ON visit_sessions(started_at);
CREATE TABLE IF NOT EXISTS visit_actions (id INTEGER PRIMARY KEY AUTOINCREMENT,visit_id TEXT NOT NULL REFERENCES visit_sessions(id),at INTEGER NOT NULL,kind TEXT NOT NULL,page TEXT NOT NULL,language TEXT NOT NULL,target TEXT NOT NULL DEFAULT '',placement TEXT NOT NULL DEFAULT '',provider TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS actions_visit ON visit_actions(visit_id,at);
CREATE TABLE IF NOT EXISTS page_events(id INTEGER PRIMARY KEY,created_at TEXT NOT NULL,page TEXT NOT NULL,ref TEXT NOT NULL DEFAULT '',param TEXT NOT NULL DEFAULT '',source TEXT NOT NULL DEFAULT '',medium TEXT NOT NULL DEFAULT '',ad_campaign TEXT NOT NULL DEFAULT '',ad TEXT NOT NULL DEFAULT '',referrer_domain TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS page_events_created ON page_events(created_at);
ALTER TABLE outbound_events ADD COLUMN entry_id INTEGER;
